#[test]
fun test_reserve_repay_all() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let now = 0;
    let mut reserve = new<MainMarket, BTC>(ctx, now);

    let base = 1000000000;
    let btc = sui::balance::create_for_testing<BTC>(base).into_coin(ctx);
    let ctokens1 = reserve.mint_ctokens<MainMarket, BTC>(btc).into_coin(ctx);

    let amount = 10000;
    let borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(amount);

    let reserve_factor = float::from_quotient(1, 100);
    // 5% per year
    let interest_rate = math::float::from_quotient(158548959918, 1000000000000000000);
    let time = 1000; // 1000 seconds
    reserve.accrue_interest(reserve_factor, interest_rate, time);

    let expected_interest = float::from_quotient(1585489599180000000, 1000000000000000000);
    let expected_debt = float::from(amount).add(expected_interest);

    assert!(reserve.debt.eq(expected_debt));
    // 1 comes from interest
    assert!(reserve.debt.floor() == amount + 1);
    let repay_btc = sui::balance::create_for_testing<BTC>(reserve.debt.floor()).into_coin(ctx);
    reserve.repay_amount<MainMarket, BTC>(repay_btc);

    // sub 1 because repaid 1 interest
    assert!(reserve.debt.eq(expected_interest.sub(float::one())));
    assert!(reserve.cash == base + 1);
    assert!(reserve.cash_reserve.eq(float::from_quotient(158548959918, 10000000000000)));
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    sui::balance::destroy_for_testing(borrowed_balance);
    std::unit_test::destroy(ctokens1);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

#[test]
fun test_reserve_exchange_rate_small_repay() {
    let admin = @0xAD;
    let mut scenario_value = sui::test_scenario::begin(admin);

    let ctx = scenario_value.ctx();
    let mut now = 0;
    let mut reserve = new<MainMarket, BTC>(ctx, now);

    let amount1 = 1000;
    let amount2 = 100;
    let amount3 = 30000;

    let btc1 = sui::balance::create_for_testing<BTC>(amount1).into_coin(ctx);
    let btc2 = sui::balance::create_for_testing<BTC>(amount2).into_coin(ctx);
    let btc3 = sui::balance::create_for_testing<BTC>(amount3).into_coin(ctx);

    let ctokens1 = reserve.mint_ctokens<MainMarket, BTC>(btc1).into_coin(ctx);
    let ctokens2 = reserve.mint_ctokens<MainMarket, BTC>(btc2).into_coin(ctx);
    let mut ctokens3 = reserve.mint_ctokens<MainMarket, BTC>(btc3).into_coin(ctx);

    let borrowed_balance = reserve.borrow_amount<MainMarket, BTC>(100);
    assert!(reserve.exchange_rate() == math::float::from_percent(100));
    assert!(reserve.debt.eq(float::from(100)));

    // just a santity check for fun
    reserve.ensure_invariants_hold<MainMarket, BTC>();

    let reserve_factor = float::from_percent(1);
    now = 2; // 2 seconds passed
    // 5% per year
    let interest_rate = math::float::from_quotient(158548959918, 1000000000000000000);

    // so new index should be 1000_000_000 + 2000
    reserve.accrue_interest(reserve_factor, interest_rate, now);

    let expected_debt = float::from_raw(100000031709791983600);
    assert!(reserve.borrow_index().value().eq(float::from_raw(1000000317097919836)));
    assert!(reserve.debt.eq(expected_debt));

    let repay = expected_debt.floor();
    let repay_btc = sui::balance::create_for_testing<BTC>(repay).into_coin(ctx);
    reserve.repay_amount<MainMarket, BTC>(repay_btc);

    assert!(reserve.debt.eq(float::from_raw(31709791983600)));
    assert!(reserve.cash == 31100);
    assert!(reserve.cash_reserve.eq(float::from_raw(317097919836)));
    // python exchange rate gives around: 1.0000000010094114
    assert!(reserve.exchange_rate() == math::float::from_raw(1000000001009411384));

    let btc1 = reserve.burn_ctokens<MainMarket, BTC>(ctokens1);
    let btc2 = reserve.burn_ctokens<MainMarket, BTC>(ctokens2);

    // because withdraw_underlying enforce ceiling, one cannot withdraw all ctoken3
    let r = ctokens3.split(1, ctx);
    let btc3 = reserve.burn_ctokens<MainMarket, BTC>(ctokens3);
    assert!(btc1.value() == amount1);
    assert!(btc2.value() == amount2);
    assert!(btc3.value() == amount3 - 1);

    reserve.ensure_invariants_hold<MainMarket, BTC>();
    assert!(reserve.debt.eq(float::from_quotient(31709791983600, 1000000000000000000)));
    assert!(reserve.cash == 1);
    assert!(reserve.cash_reserve.eq(float::from_raw(317097919836)));

    sui::balance::destroy_for_testing(borrowed_balance);
    std::unit_test::destroy(r);
    std::unit_test::destroy(btc1);
    std::unit_test::destroy(btc2);
    std::unit_test::destroy(btc3);
    std::unit_test::destroy(reserve);
    scenario_value.end();
}

