    20→
    21→/// Create a new interest model
    22→public(package) fun new(
    23→    base_borrow_rate_per_sec: Decimal,
    24→    borrow_rate_on_mid_kink: Decimal,
    25→    mid_kink: Decimal,
    26→    borrow_rate_on_high_kink: Decimal,
    27→    high_kink: Decimal,
    28→    max_borrow_rate: Decimal,
    29→): InterestModel {
    30→    InterestModel {
    31→        base_borrow_rate_per_sec,
    32→        borrow_rate_on_mid_kink,
    33→        mid_kink,
    34→        borrow_rate_on_high_kink,
    35→        high_kink,
    36→        max_borrow_rate,
    37→    }
    38→}
    39→
    40→// Return the interest rate under the given utilization rate
    41→// Notice: the interest rate is scaled by a factor, because it's too small to be used directly
    42→public(package) fun calc_interest(
    43→    interest_model: &InterestModel,
    44→    util_rate: Decimal,
    45→): Decimal {
