     1→module protocol::debt;
     2→
     3→use protocol::error;
     4→use math::float::Decimal;
     5→
     6→public struct Debt has copy, drop, store {
     7→    amount: Decimal,
     8→    borrow_index: Decimal,
     9→}
    10→
    11→public(package) fun new(
    12→    amount: Decimal,
    13→    borrow_index: Decimal,
    14→): Debt {
    15→    Debt { amount, borrow_index }
    16→}
    17→
    18→public(package) fun has_debt(self: &Debt): bool {
    19→    !self.amount.is_zero()
    20→}
    21→
    22→public(package) fun debt(self: &Debt, borrow_index: Decimal): Decimal {
    23→    // avoid any math operation
    24→    if (borrow_index.eq(self.borrow_index)) { return self.amount };
    25→    self.amount.mul(borrow_index).div(self.borrow_index)
    26→}
    27→
    28→/// This operation is unsafe because debt might not be up to date with latest market, accrue_interest first
    29→public(package) fun unsafe_debt_amount(self: &Debt): Decimal {
    30→    self.amount
    31→}
    32→
    33→/// The debt is cleared
    34→public(package) fun cleared(self: &mut Debt) {
    35→    self.amount = math::float::zero();
    36→}
    37→
    38→/// This operation is unsafe because debt might not be up to date with latest market, accrue_interest first
    39→public(package) fun unsafe_decrease(self: &mut Debt, amount: Decimal) {
    40→    self.amount = self.amount.sub(amount);
    41→}
    42→
    43→/// This operation is unsafe because debt might not be up to date with latest market, accrue_interest first
    44→public(package) fun unsafe_increase(self: &mut Debt, amount: Decimal) {
    45→    self.amount = self.amount.add(amount);
    46→}
    47→
    48→/// Accrue the interest, returns the interest changed
    49→public(package) fun accrue_interest(self: &mut Debt, new_borrow_index: Decimal) {
    50→    assert!(self.borrow_index.le(new_borrow_index), error::invariant_borrow_index_incremental());
    51→
    52→    // // If the borrow index hasn't changed, there is no interest to accrue.
    53→    if (self.borrow_index.eq(new_borrow_index)) return;
    54→
    55→    self.amount = self.debt(new_borrow_index);
    56→    self.borrow_index = new_borrow_index;
    57→}
    58→
    59→public(package) fun borrow_index(self: &Debt): &Decimal {
    60→    &self.borrow_index
    61→}
    62→
    63→#[test_only]
    64→public fun snapshot(self: &Debt): (Decimal, Decimal) {
    65→    (self.amount, self.borrow_index)
    66→}

